import { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';

export interface ProfileCardProps {
  displayName: string;
  bio: string;
}

export function ProfileCard({ displayName, bio }: ProfileCardProps): JSX.Element {
  const [expanded, setExpanded] = useState(false);

  const toggle = (): void => setExpanded(prev => !prev);

  return (
    <View style={styles.card}>
      <Text style={styles.name}>{displayName}</Text>
      <TouchableOpacity
        onPress={toggle}
        accessibilityRole="button"
        accessibilityLabel={expanded ? 'Collapse bio' : 'Expand bio'}
        accessibilityState={{ expanded }}
      >
        <Text style={styles.bio} numberOfLines={expanded ? undefined : 2}>
          {bio}
        </Text>
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  card: { padding: 16, backgroundColor: '#F2F2F7', borderRadius: 12 },
  name: { fontSize: 18, fontWeight: '700' },
  bio: { fontSize: 14, color: '#333', marginTop: 8 },
});
